package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string          // PIC X len=1 = "N"
var WsBal decimal.Decimal     // PIC 9(8)V99 len=10 = 0
var WsYear int64              // PIC 99 len=2 = 0
var WsCount int64             // PIC 99 len=2 = 0
var WsBalEd string            // PIC ZZ,ZZZ,ZZ9.99 len=13

var schedRec SchedRec

var schedLines []string
var schedIdx int
var schedFile *os.File

func parseImplied2(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	// keep only digits and sign if any
	t = strings.TrimSpace(t)
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// remove any non-digit characters (spaces)
		clean := ""
		for _, c := range t {
			if c >= '0' && c <= '9' {
				clean += string(c)
			}
		}
		if clean == "" {
			return decimal.Zero
		}
		n, _ = strconv.ParseInt(clean, 10, 64)
	}
	return decimal.New(n, -2)
}

func parseInt1(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func formatPIC99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func fitBal(v decimal.Decimal) decimal.Decimal {
	scaled := v.Shift(2).IntPart()
	mod := scaled % 10000000000
	return decimal.New(mod, -2)
}

func formatWsBalEd(v decimal.Decimal) string {
	// v is PIC 9(8)V99, scale 2
	scaled := v.Shift(2).IntPart()
	if scaled < 0 {
		scaled = -scaled
		// positive handling only needed; negatives not expected
	}
	scaled = scaled % 10000000000
	intPart := scaled / 100
	fracPart := scaled % 100
	s := fmt.Sprintf("%08d", intPart)
	digits := []byte(s) // 8 digits
	// picture ZZ,ZZZ,ZZ9.99 -> integer chars: Z Z , Z Z Z , Z Z 9
	// map digits[0..7] to positions
	out := make([]byte, 0, 13)
	significant := false
	// helper to check if any later digit (including current) is nonzero
	// or if this is the last digit (always significant)
	// Determine: leading zeros suppressed until first nonzero or last pos
	// Find first significant index: first nonzero, or 7
	firstSig := 7
	for i := 0; i < 8; i++ {
		if digits[i] != '0' {
			firstSig = i
			break
		}
	}
	// positions:
	// idx 0 -> digits[0] Z
	// idx 1 -> digits[1] Z
	// comma
	// idx 2,3,4 -> digits[2,3,4] Z
	// comma
	// idx 5,6 -> digits[5,6] Z
	// idx 7 -> digits[7] 9
	emitZ := func(di int) byte {
		if di >= firstSig {
			significant = true
			return digits[di]
		}
		return ' '
	}
	_ = significant
	b0 := emitZ(0)
	b1 := emitZ(1)
	out = append(out, b0, b1)
	// comma 1
	if firstSig < 2 {
		out = append(out, ',')
	} else {
		out = append(out, ' ')
	}
	out = append(out, emitZ(2), emitZ(3), emitZ(4))
	if firstSig < 5 {
		out = append(out, ',')
	} else {
		out = append(out, ' ')
	}
	out = append(out, emitZ(5), emitZ(6))
	out = append(out, digits[7])
	out = append(out, '.')
	out = append(out, byte('0'+fracPart/10), byte('0'+fracPart%10))
	return string(out)
}

func MAINPARA() {
	// OPEN INPUT SCHED-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file missing, treat as empty?
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	schedFile = f
	scanner := bufio.NewScanner(f)
	// allow long lines
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	schedLines = nil
	for scanner.Scan() {
		line := scanner.Text()
		// strip trailing \r if present (CRLF)
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		schedLines = append(schedLines, line)
	}
	schedIdx = 0
	WsEofFlag = "N"
	WsBal = decimal.Zero
	WsYear = 0
	WsCount = 0
	WsBalEd = ""

	READPARA()
	for !(WsEofFlag == "Y") {
		PROCESSPARA()
	}
	schedFile.Close()
	// DISPLAY "SCHEDULES: " WS-COUNT
	fmt.Printf("%s%s\n", "SCHEDULES: ", formatPIC99(WsCount))
}

func READPARA() {
	if schedIdx >= len(schedLines) {
		WsEofFlag = "Y"
		return
	}
	line := schedLines[schedIdx]
	schedIdx++
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	schedRec.ScAcct = line[0:4]
	schedRec.ScPrin = parseImplied2(line[4:11])
	schedRec.ScRate = parseImplied2(line[11:15])
	schedRec.ScYears = parseInt1(line[15:16])
}

func PROCESSPARA() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = fitBal(schedRec.ScPrin)
	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	WsYear = 1
	for !(WsYear > schedRec.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		factor := decimal.NewFromInt(1).Add(schedRec.ScRate.Shift(-2))
		exact := WsBal.Mul(factor)
		rounded := exact.Round(2)
		WsBal = fitBal(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		fmt.Printf("%s%s%s%s%s\n", schedRec.ScAcct, " Y", formatPIC99(WsYear), " ", WsBalEd)
		WsYear = (WsYear + 1) % 100
		// handle wrap: if modulo gives 0 after 99, keep 0 (COBOL would)
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s%s%s\n", schedRec.ScAcct, " FINAL ", WsBalEd)
	WsCount = (WsCount + 1) % 100
	READPARA()
}

func main() {
	MAINPARA()
}
